def transform(grid):
 h,w=len(grid),len(grid[0]); a=[r[:] for r in grid]
 bar=next(( (r,c) for r in range(h) for c in range(w) if a[r][c]==2),None)
 dr,dc=(1,0) if bar and bar[0]==0 else (-1,0) if bar and bar[0]==h-1 else (0,1) if bar and bar[1]==0 else (0,-1)
 seen=set(); objs=[]
 for r in range(h):
  for c in range(w):
   v=a[r][c]
   if not v or v==2 or (r,c) in seen: continue
   q=[(r,c)]; seen.add((r,c)); k=0
   while k<len(q):
    x,y=q[k]; k+=1
    for nx,ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
     if 0<=nx<h and 0<=ny<w and (nx,ny) not in seen and a[nx][ny]==v: seen.add((nx,ny));q.append((nx,ny))
   objs.append((v,q))
 # nearest-to-bar objects move first; rigid slide maximally
 objs.sort(key=lambda z:min(r*dr+c*dc for r,c in z[1]))
 for v,cells in objs:
  for r,c in cells:a[r][c]=0
  while True:
   nxt=[(r+dr,c+dc) for r,c in cells]
   if any(not(0<=r<h and 0<=c<w) or a[r][c]!=0 for r,c in nxt):break
   cells=nxt
  for r,c in cells:a[r][c]=v
 return a
