def transform(grid):
 h,w=len(grid),len(grid[0]); a=[r[:] for r in grid]; bar=next(( (r,c) for r in range(h) for c in range(w) if a[r][c]==2),None)
 dr,dc=(-1,0) if bar[0]==0 else (1,0) if bar[0]==h-1 else (0,-1) if bar[1]==0 else (0,1)
 seen=set(); objs=[]
 for r in range(h):
  for c in range(w):
   v=a[r][c]
   if v in (0,2) or (r,c) in seen: continue
   q=[(r,c)]; seen.add((r,c))
   for x,y in q:
    for nx,ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
     if 0<=nx<h and 0<=ny<w and (nx,ny) not in seen and a[nx][ny]==v: seen.add((nx,ny)); q.append((nx,ny))
   objs.append((v,q))
 while True:
  occ={p:i for i,(_,cells) in enumerate(objs) for p in cells}; moving=[]
  for i,(v,cells) in enumerate(objs):
   nxt=[(r+dr,c+dc) for r,c in cells]
   if all(0<=r<h and 0<=c<w and (p not in occ or occ[p]==i) for p,(r,c) in zip(cells,nxt)): moving.append(i)
  if not moving: break
  for i in moving:
   v,cells=objs[i]; objs[i]=(v,[(r+dr,c+dc) for r,c in cells])
 out=[[0]*w for _ in range(h)]
 for r in range(h):
  for c in range(w):
   if grid[r][c]==2:out[r][c]=2
 for v,cells in objs:
  for r,c in cells:out[r][c]=v
 return out
